<template>
  <div class="al-root">
    <!-- ── LOADING ─────────────────────────────────────────────────────── -->
    <div v-if="loading" class="d-flex flex-column align-center justify-center pa-16" style="gap:14px;">
      <v-progress-circular size="36" width="3" indeterminate color="teal darken-1" />
      <span class="caption grey--text">Loading applicants…</span>
    </div>

    <!-- ── NOT FOUND ───────────────────────────────────────────────────── -->
    <div v-else-if="notFound" class="d-flex flex-column align-center pa-16 text-center" style="gap:12px;">
      <v-icon size="48" color="grey lighten-1">mdi-alert-circle-outline</v-icon>
      <div class="subtitle-1 font-weight-bold grey--text text--darken-1">Advertisement not found</div>
      <div class="body-2 grey--text" style="max-width:360px;">The requested advertisement could not be loaded.</div>
      <v-btn outlined color="teal darken-1" @click="goBack">
        <v-icon left small>mdi-arrow-left</v-icon>Back to Recruitment
      </v-btn>
    </div>

    <!-- ── CONTENT ─────────────────────────────────────────────────────── -->
    <template v-else>
      <!-- ── HERO ────────────────────────────────────────────────────── -->
      <header class="al-hero">
        <div class="al-hero__bg">
          <div class="al-hero__grid"></div>
          <div class="al-hero__glow"></div>
        </div>
        <div class="al-hero__inner">
          <div class="al-hero__left">
            <v-btn text dark small class="mb-3" @click="goBack">
              <v-icon left small>mdi-arrow-left</v-icon>Back to Recruitment
            </v-btn>
            <div class="al-hero__eyebrow">
              <span class="al-hero__dot"></span>
              Applicant List
            </div>
            <h1 class="al-hero__title">
              {{ advert.name || "(Untitled Position)" }}
            </h1>
            <div class="al-hero__meta-row">
              <span v-if="advert.facility" class="al-hero__meta-item">
                <v-icon size="11" color="rgba(255,255,255,0.4)">mdi-hospital-building</v-icon>
                {{ advert.facility }}
              </span>
              <span v-if="advert.department" class="al-hero__meta-item">
                <v-icon size="11" color="rgba(255,255,255,0.4)">mdi-domain</v-icon>
                {{ advert.department }}
              </span>
              <span v-if="advert.closingDate" class="al-hero__meta-item">
                <v-icon size="11" color="rgba(255,255,255,0.4)">mdi-calendar-end</v-icon>
                Closes {{ formatDate(advert.closingDate) }}
              </span>
            </div>
          </div>
          <div class="al-hero__right">
            <div class="al-hero__stat">
              <div class="al-hero__stat-num">{{ allApplications.length }}</div>
              <div class="al-hero__stat-label">Total Applications</div>
            </div>
            <div class="al-hero__stat">
              <div class="al-hero__stat-num">{{ totalShortlists }}</div>
              <div class="al-hero__stat-label">Shortlisted</div>
            </div>
            <div class="al-hero__stat">
              <div class="al-hero__stat-num">{{ totalOffered }}</div>
              <div class="al-hero__stat-label">Offered</div>
            </div>
            <div class="al-hero__stat">
              <div class="al-hero__stat-num">
                {{ advert.advertisedVacancies }}
              </div>
              <div class="al-hero__stat-label">Posts</div>
            </div>
          </div>
        </div>
      </header>

      <!-- ── BODY ─────────────────────────────────────────────────────── -->
      <div class="al-body">
        <!-- ── SCORING TOOLBAR ─────────────────────────────────────── -->
        <v-card outlined class="mb-4">
          <v-card-text class="d-flex align-center flex-wrap py-3" style="gap:12px;">
            <v-btn
              color="indigo darken-1"
              dark
              depressed
              :loading="analysing"
              @click="runAnalysis"
            >
              <v-icon left small>mdi-chart-bar</v-icon>
              {{ analysed ? 'Re-run Analysis' : 'Analyse Applicants' }}
            </v-btn>

            <span v-if="analysed" class="caption grey--text">
              <v-icon x-small color="teal darken-1">mdi-check-circle</v-icon>
              Analysis complete — sorted by match score
            </span>

            <close-hiring-button
              :advert-id="advertId"
              :vacancies="advert.advertisedVacancies"
              :label="advert.name"
              :disabled="hiringClosed"
              :button-text="hiringClosed ? 'Hiring Closed' : 'Close Hiring'"
              @closed="loadCounts"
            />

            <v-spacer />

            <!-- Score legend -->
            <v-menu open-on-hover offset-y>
              <template v-slot:activator="{ on }">
                <v-btn text x-small color="grey darken-1" v-on="on">
                  <v-icon left x-small>mdi-information-outline</v-icon>Score Guide
                </v-btn>
              </template>
              <v-card outlined class="pa-3" style="min-width:240px;">
                <div class="caption font-weight-bold text-uppercase grey--text mb-2">Score Legend</div>
                <div v-for="band in scoreBands" :key="band.label" class="d-flex align-center mb-1" style="gap:8px;">
                  <v-chip x-small :color="band.color" dark style="width:80px; justify-content:center;">{{ band.range }}</v-chip>
                  <span class="caption">{{ band.label }}</span>
                </div>
              </v-card>
            </v-menu>
          </v-card-text>
        </v-card>

        <!-- ── FILTERS ──────────────────────────────────────────────── -->
        <v-card outlined class="mb-4">
          <v-card-text class="pb-1">
            <v-row dense>
              <v-col cols="12" sm="6" md="3">
                <v-text-field
                  v-model="filter.name"
                  label="Search by full name"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-magnify"
                  class="ma-1"
                />
              </v-col>
              <v-col cols="12" sm="6" md="2">
                <v-select
                  v-model="filter.gender"
                  label="Gender"
                  :items="genderOptions"
                  dense
                  outlined
                  hide-details
                  clearable
                  class="ma-1"
                />
              </v-col>
              <v-col cols="12" sm="6" md="2">
                <v-select
                  v-model="filter.status"
                  label="Status"
                  :items="statusOptions"
                  item-text="text"
                  item-value="value"
                  dense
                  outlined
                  hide-details
                  clearable
                  class="ma-1"
                />
              </v-col>
              <v-col cols="12" sm="6" md="2">
                <v-text-field
                  v-model="filter.nationalId"
                  label="National ID"
                  dense
                  outlined
                  hide-details
                  clearable
                  class="ma-1"
                />
              </v-col>
              <v-col cols="12" sm="6" md="2">
                <v-text-field
                  v-model="filter.passportNumber"
                  label="Passport No"
                  dense
                  outlined
                  hide-details
                  clearable
                  class="ma-1"
                />
              </v-col>
              <v-col cols="12" sm="6" md="1" class="d-flex align-center">
                <v-btn
                  v-if="hasActiveFilters"
                  text
                  small
                  color="grey darken-1"
                  class="ma-1"
                  @click="resetFilters"
                >
                  <v-icon small left>mdi-close</v-icon>
                  Clear
                </v-btn>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>

        <!-- ── TABLE ────────────────────────────────────────────────── -->
        <v-data-table
          :headers="headers"
          :items="filteredApplications"
          :loading="loadingApplicants"
          loading-text="Loading applicant profiles…"
          :no-data-text="
            hasActiveFilters
              ? 'No applicants match the search criteria'
              : 'No applications received yet'
          "
          :footer-props="{
            'items-per-page-options': [10, 25, 50],
            'items-per-page-text': 'Rows per page',
          }"
          class="elevation-1"
          style="cursor: pointer"
          @click:row="viewApplication"
        >
          <!-- Full name + avatar -->
          <template #[`item.fullName`]="{ item }">
            <div class="d-flex align-center">
              <v-avatar
                size="32"
                color="teal darken-1"
                class="mr-2 flex-shrink-0"
              >
                <span class="white--text text-caption font-weight-bold">{{
                  initials(item.fullName)
                }}</span>
              </v-avatar>
              <div>
                <div class="font-weight-medium al-cell-name">
                  {{ item.fullName || "—" }}
                </div>
                <div v-if="item.email" class="caption grey--text">
                  {{ item.email }}
                </div>
              </div>
            </div>
          </template>

          <!-- National ID (mono) -->
          <template #[`item.nationalId`]="{ item }">
            <span class="al-mono">{{ item.nationalId || "—" }}</span>
          </template>

          <!-- Passport (mono) -->
          <template #[`item.passportNumber`]="{ item }">
            <span class="al-mono">{{ item.passportNumber || "—" }}</span>
          </template>

          <!-- Applied date (mono) -->
          <template #[`item.appliedOn`]="{ item }">
            <span class="al-mono">{{ formatDate(item.appliedOn) }}</span>
          </template>

          <!-- Status chip -->
          <template #[`item.statusCode`]="{ item }">
            <v-chip x-small
              :color="statusChipColor(item.statusCode)"
              :text-color="statusChipText(item.statusCode)"
            >{{ item.statusDisplay || item.statusCode || "—" }}</v-chip>
          </template>

          <!-- Match score -->
          <template #[`item.score`]="{ item }">
            <div v-if="item.score != null" class="d-flex align-center" style="gap:6px;">
              <v-chip x-small dark :color="scoreBandColor(item.score)" style="min-width:44px; justify-content:center;">
                {{ item.score }}%
              </v-chip>
              <span class="caption grey--text d-none d-md-inline">{{ item.scoreLabel }}</span>
            </div>
            <span v-else class="caption grey--text">—</span>
          </template>

          <!-- Actions -->
          <template #[`item.actions`]="{ item }">
            <v-btn
              icon
              small
              title="Review application"
              @click.stop="viewApplication(item)"
            >
              <v-icon small>mdi-eye-outline</v-icon>
            </v-btn>
          </template>
        </v-data-table>
      </div>
    </template>
  </div>
</template>

<script>
const APP_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/application-profile";
const EXT_APPLICANT =
  "http://ihris.org/fhir/StructureDefinition/ihris-external-applicant-reference";
const EXT_PRACTITIONER =
  "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference";
const EXT_STATUS =
  "http://ihris.org/fhir/StructureDefinition/application-status";
const EXT_DATE = "http://ihris.org/fhir/StructureDefinition/event-date";
const EXT_ADV_NAME =
  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name";
const EXT_ADV_END = "http://ihris.org/fhir/StructureDefinition/end-date";
const EXT_ADV_MAX =
  "http://ihris.org/fhir/StructureDefinition/maximum-practitioners";
const EXT_ADV_POS =
  "http://ihris.org/fhir/StructureDefinition/position-reference";
const EXT_DEPT = "http://ihris.org/fhir/StructureDefinition/department";
const EXT_FACILITY = "http://ihris.org/fhir/StructureDefinition/facility";
const EXT_HIRING_STATUS =
  "http://ihris.org/fhir/StructureDefinition/hiring-status";

import CloseHiringButton from "../shared/CloseHiringButton.vue";

export default {
  name: "ApplicantList",
  components: { CloseHiringButton },
  props: ["queries"],

  data() {
    return {
      loading: true,
      loadingApplicants: false,
      notFound: false,
      analysing: false,
      analysed: false,

      advert: {
        id: null,
        name: "",
        department: "",
        facility: "",
        closingDate: null,
        advertisedVacancies: 0,
        positionRef: null,
        hiringStatus: null,
      },

      allApplications: [],

      filter: {
        name: "",
        gender: "",
        nationalId: "",
        passportNumber: "",
        status: "",
      },

      totalShortlists: 0,
      totalOffered: 0,

      genderOptions: ["Male", "Female"],
      statusOptions: [
        { text: "Shortlisted", value: "shortlisted" },
        { text: "Not Shortlisted", value: "notshortlisted" },
        { text: "Job Offered", value: "offered" },
        { text: "Not Offered", value: "notoffered" },
      ],

      scoreBands: [
        { range: "80–100%", label: "Strong Match",   color: "success" },
        { range: "60–79%",  label: "Good Match",     color: "teal darken-1" },
        { range: "40–59%",  label: "Partial Match",  color: "orange darken-1" },
        { range: "20–39%",  label: "Weak Match",     color: "deep-orange" },
        { range: "0–19%",   label: "No Match",       color: "error" },
      ],

      headers: [
        { text: "Full Name",   value: "fullName",       width: "220px" },
        { text: "Gender",      value: "gender" },
        { text: "National ID", value: "nationalId" },
        { text: "Passport No", value: "passportNumber" },
        { text: "Phone",       value: "phone" },
        { text: "Applied On",  value: "appliedOn" },
        { text: "Status",      value: "statusCode" },
        { text: "Match Score", value: "score",          width: "140px" },
        { text: "", value: "actions", sortable: false, align: "right", width: "48px" },
      ],
    };
  },

  computed: {
    advertId() {
      return (
        this.queries &&
        (this.queries.advertId || this.queries.id || this.queries.advert)
      );
    },

    hiringClosed() {
      return this.advert.hiringStatus?.code === "closed";
    },

    hasActiveFilters() {
      return !!(
        this.filter.name ||
        this.filter.gender ||
        this.filter.nationalId ||
        this.filter.passportNumber ||
        this.filter.status
      );
    },

    filteredApplications() {
      const name = this.filter.name.trim().toLowerCase();
      const gender = this.filter.gender.trim().toLowerCase();
      const nid = this.filter.nationalId.trim().toLowerCase();
      const pass = this.filter.passportNumber.trim().toLowerCase();
      const status = this.filter.status;

      return this.allApplications.filter((item) => {
        if (name && !(item.fullName || "").toLowerCase().includes(name))
          return false;
        if (gender && (item.gender || "").toLowerCase() !== gender)
          return false;
        if (nid && !(item.nationalId || "").toLowerCase().includes(nid))
          return false;
        if (pass && !(item.passportNumber || "").toLowerCase().includes(pass))
          return false;
        if (status && (item.statusCode || "") !== status) return false;
        return true;
      });
    },
  },

  async mounted() {
    this.countShortlists();
    if (!this.advertId) {
      this.notFound = true;
      this.loading = false;
      return;
    }
    await this.loadAdvert();
    this.loading = false;
    // Load applications in background so the header renders immediately
    this.loadingApplicants = true;
    try {
      await this.loadApplications();
    } finally {
      this.loadingApplicants = false;
    }
    this.loadCounts();
    this.loadSavedScores();
  },

  methods: {
    // ── Load advert header info ─────────────────────────────────────
    async loadAdvert() {
      try {
        const res = await fetch(`/fhir/Basic/${this.advertId}`);
        if (!res.ok) {
          this.notFound = true;
          return;
        }
        const data = await res.json();
        const ext = (url, type) => {
          const e = (data.extension || []).find((x) => x.url === url);
          return e ? e[type] : null;
        };

        this.advert.id = data.id;
        this.advert.name = ext(EXT_ADV_NAME, "valueString") || "";
        this.advert.closingDate = ext(EXT_ADV_END, "valueDate") || null;
        this.advert.advertisedVacancies = ext(EXT_ADV_MAX, "valueInteger") || 0;
        this.advert.hiringStatus = ext(EXT_HIRING_STATUS, "valueCoding") || null;

        const posRef = ext(EXT_ADV_POS, "valueReference");
        if (posRef && posRef.reference) {
          this.advert.positionRef = posRef.reference;
          await this.resolvePositionMeta(posRef.reference);
        }
      } catch (err) {
        console.error("loadAdvert error", err);
        this.notFound = true;
      }
    },

    // ── Resolve department + facility from linked position ──────────
    async resolvePositionMeta(positionReference) {
      try {
        const posId = positionReference.split("/")[1];
        const res = await fetch(`/fhir/Basic/${posId}`);
        if (!res.ok) return;
        const pos = await res.json();
        const ext = (url, type) => {
          const e = (pos.extension || []).find((x) => x.url === url);
          return e ? e[type] : null;
        };
        const deptCoding = ext(EXT_DEPT, "valueCoding");
        if (deptCoding) {
          this.advert.department = deptCoding.display || deptCoding.code || "";
        }
        const facRef = ext(EXT_FACILITY, "valueReference");
        if (facRef && facRef.reference) {
          try {
            const fRes = await fetch(`/fhir/${facRef.reference}`);
            if (fRes.ok) {
              const fData = await fRes.json();
              this.advert.facility = fData.name || "";
            }
          } catch (e) {
            /* ignore */
          }
        }
      } catch (err) {
        /* ignore */
      }
    },

    // ── Load all applications for this advert, sorted ascending ─────
    async loadApplications() {
      try {
        // Fetch all applications (up to 500) sorted oldest-first
        const params = new URLSearchParams({
          _profile: APP_PROFILE,
          advertisedvacancy: "Basic/" + this.advertId,
          _count: "500",
          _total: "accurate",
          _sort: "_lastUpdated", // ascending = first applied on top
        });

        const res = await fetch(`/fhir/Basic?${params}`);
        if (!res.ok) return;
        const bundle = await res.json();
        const entries = (bundle.entry || [])
          .map((e) => e.resource)
          .filter(Boolean);

        // Collect unique applicant refs
        const applicantRefs = [
          ...new Set(
            entries
              .map((r) => {
                const e = (r.extension || []).find(
                  (x) => x.url === EXT_APPLICANT,
                );
                return e
                  ? e.valueReference && e.valueReference.reference
                  : null;
              })
              .filter(Boolean),
          ),
        ];

        // Collect unique practitioner refs (internal applicants)
        const practitionerRefs = [
          ...new Set(
            entries
              .map((r) => {
                const e = (r.extension || []).find(
                  (x) => x.url === EXT_PRACTITIONER,
                );
                return e
                  ? e.valueReference && e.valueReference.reference
                  : null;
              })
              .filter(Boolean),
          ),
        ];

        // Batch-fetch all applicant profiles in parallel
        const profileMap = {};
        await Promise.all(
          applicantRefs.map(async (ref) => {
            try {
              const id = ref.split("/")[1];
              const r = await fetch(`/fhir/Basic/${id}`);
              if (r.ok) profileMap[ref] = await r.json();
            } catch (e) {
              /* ignore */
            }
          }),
        );

        // Batch-fetch all internal applicant (Practitioner) records in parallel
        const practitionerMap = {};
        await Promise.all(
          practitionerRefs.map(async (ref) => {
            try {
              const id = ref.split("/")[1];
              const r = await fetch(`/fhir/Practitioner/${id}`);
              if (r.ok) practitionerMap[ref] = await r.json();
            } catch (e) {
              /* ignore */
            }
          }),
        );

        // Join application + applicant data
        this.allApplications = entries.map((r) => {
          const applicantRef = (
            (r.extension || []).find((x) => x.url === EXT_APPLICANT) || {}
          ).valueReference;
          const practitionerRef = (
            (r.extension || []).find((x) => x.url === EXT_PRACTITIONER) || {}
          ).valueReference;
          const profile = applicantRef
            ? profileMap[applicantRef.reference]
            : null;
          const practitioner = practitionerRef
            ? practitionerMap[practitionerRef.reference]
            : null;

          const pExt = (url, type) => {
            const e = ((profile && profile.extension) || []).find((x) =>
              x.url.endsWith("/" + url),
            );
            return e ? e[type] : null;
          };
          const pCoding = (url) => {
            const e = ((profile && profile.extension) || []).find((x) =>
              x.url.endsWith("/" + url),
            );
            return e && e.valueCoding ? e.valueCoding.display : null;
          };

          const statusExt = (r.extension || []).find(
            (x) => x.url === EXT_STATUS,
          );
          const dateExt = (r.extension || []).find((x) => x.url === EXT_DATE);

          let fullName;
          let gender;
          let nationalId;
          let passportNumber;
          let phone;
          let email;

          if (practitioner) {
            const name = (practitioner.name && practitioner.name[0]) || {};
            fullName =
              name.text ||
              [...(name.given || []), name.family].filter(Boolean).join(" ");
            gender = practitioner.gender
              ? practitioner.gender.charAt(0).toUpperCase() +
                practitioner.gender.slice(1)
              : null;

            const telecom = practitioner.telecom || [];
            phone = (telecom.find((t) => t.system === "phone") || {}).value;
            email = (telecom.find((t) => t.system === "email") || {}).value;

            const identifiers = practitioner.identifier || [];
            const findIdentifier = (code) =>
              (
                identifiers.find(
                  (id) =>
                    id.type &&
                    id.type.coding &&
                    id.type.coding.some((c) => c.code === code),
                ) || {}
              ).value;
            nationalId = findIdentifier("nationalid");
            passportNumber = findIdentifier("passport");
          } else {
            const firstName = pExt("first-name", "valueString") || "";
            const middleName = pExt("middle-name", "valueString") || "";
            const surname = pExt("surname", "valueString") || "";
            fullName =
              [firstName, middleName, surname].filter(Boolean).join(" ") ||
              pExt("ihris-basic-name", "valueString") ||
              "";
            gender = pCoding("person-gender");
            nationalId = pExt("national-id", "valueString");
            passportNumber = pExt("passport-number", "valueString");
            phone = pExt("phone", "valueString");
            email = pExt("email", "valueString");
          }

          return {
            applicationId: r.id,
            applicantRef: applicantRef ? applicantRef.reference : null,
            fullName,
            gender,
            nationalId,
            passportNumber,
            phone,
            email,
            appliedOn: dateExt ? dateExt.valueDate : null,
            statusCode:
              statusExt && statusExt.valueCoding
                ? statusExt.valueCoding.code
                : null,
            statusDisplay:
              statusExt && statusExt.valueCoding
                ? statusExt.valueCoding.display
                : null,
          };
        });
      } catch (err) {
        console.error("loadApplications error", err);
      }
    },

    async countShortlists() {
      const params = new URLSearchParams({
        _profile: APP_PROFILE,
        advertisedvacancy: "Basic/" + this.advertId,
        posappstatus: "shortlisted",
        _count: 0,
        _total: "accurate",
      });
      const res = await fetch(`/fhir/Basic?${params}`);
      const bundle = await res.json();
      return bundle.total || 0;
    },

    async countOffered() {
      const params = new URLSearchParams({
        _profile: APP_PROFILE,
        advertisedvacancy: "Basic/" + this.advertId,
        posappstatus: "offered",
        _count: 0,
        _total: "accurate",
      });
      const res = await fetch(`/fhir/Basic?${params}`);
      const bundle = await res.json();
      return bundle.total || 0;
    },

    async loadCounts() {
      try {
        const [shortlisted, offered] = await Promise.all([
          this.countShortlists(),
          this.countOffered(),
        ]);
        this.totalOffered = offered;
        this.totalShortlists = shortlisted + offered;
      } catch (err) {
        console.error("loadCounts error", err);
      }
    },

    // ── Navigation ────────────────────────────────────────────────────
    goBack() {
      if (this.queries && this.queries.from === "vacancy-detail") {
        this.$router.push({
          path: "/custom/vacancy-detail",
          query: { path: "/lesotho/components/recruitment", id: this.advertId },
        });
      } else {
        this.$router.push({
          path: "/custom/index",
          query: { path: "/lesotho/components/recruitment" },
        });
      }
    },

    viewApplication(item) {
      this.$router.push({
        path: "/custom/hr-application-review",
        query: {
          path: "/lesotho/components/recruitment",
          applicationId: item.applicationId,
          advertId: this.advertId,
        },
      });
    },

    // ── Helpers ───────────────────────────────────────────────────────
    initials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .slice(0, 2)
        .map((w) => w[0])
        .join("")
        .toUpperCase();
    },

    formatDate(d) {
      if (!d) return "—";
      return new Date(d).toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    // ── Scoring ──────────────────────────────────────────────────────────
    async runAnalysis() {
      this.analysing = true;
      try {
        const res = await fetch(`/site/scoring/advert/${this.advertId}/analyse`, { method: "POST" });
        if (!res.ok) {
          const err = await res.json();
          console.error("Analysis error:", err);
          return;
        }
        const { results } = await res.json();
        this.applyScores(results);
        // Sort by score descending after analysis
        this.allApplications.sort((a, b) => (b.score ?? -1) - (a.score ?? -1));
        this.analysed = true;
      } catch (err) {
        console.error("runAnalysis error", err);
      } finally {
        this.analysing = false;
      }
    },

    async loadSavedScores() {
      try {
        const res = await fetch(`/site/scoring/advert/${this.advertId}/scores`);
        if (!res.ok) return;
        const { results } = await res.json();
        const hasAny = results.some(r => r.score != null);
        if (!hasAny) return;
        this.applyScores(results);
        this.allApplications.sort((a, b) => (b.score ?? -1) - (a.score ?? -1));
        this.analysed = true;
      } catch (_) { /* non-critical */ }
    },

    applyScores(results) {
      const scoreMap = {};
      for (const r of results) {
        if (r.applicationId && r.score != null) {
          scoreMap[r.applicationId] = { score: r.score, scoreLabel: r.label };
        }
      }
      this.allApplications = this.allApplications.map(app => ({
        ...app,
        ...(scoreMap[app.applicationId] || {}),
      }));
    },

    scoreBandColor(score) {
      if (score >= 80) return "success";
      if (score >= 60) return "teal darken-1";
      if (score >= 40) return "orange darken-1";
      if (score >= 20) return "deep-orange";
      return "error";
    },

    statusChipColor(code) {
      const m = {
        underreview:    "blue lighten-5",
        shortlisted:    "green lighten-5",
        notshortlisted: "red lighten-5",
        offered:        "orange lighten-5",
        notoffered:     "red lighten-5",
        appointed:      "green lighten-5",
        withdrawn:      "grey lighten-3",
        rejected:       "red lighten-5",
      };
      return m[code] || "grey lighten-3";
    },

    statusChipText(code) {
      const m = {
        underreview:    "blue darken-2",
        shortlisted:    "green darken-2",
        notshortlisted: "red darken-2",
        offered:        "orange darken-2",
        notoffered:     "red darken-2",
        appointed:      "green darken-3",
        withdrawn:      "grey darken-1",
        rejected:       "red darken-2",
      };
      return m[code] || "grey darken-1";
    },

    resetFilters() {
      this.filter = {
        name: "",
        gender: "",
        nationalId: "",
        passportNumber: "",
        status: "",
      };
    },
  },
};
</script>

