<template>
  <span>
    <slot name="activator" :open="open" :disabled="disabled">
      <v-btn outlined color="error" :disabled="disabled" @click="open">
        <v-icon left small>mdi-account-lock-outline</v-icon>
        {{ buttonText }}
      </v-btn>
    </slot>

    <v-dialog v-model="dialog" max-width="460" persistent>
      <v-card>
        <v-card-title class="text-h6 font-weight-bold">
          Close Hiring
        </v-card-title>
        <v-card-text>
          <div v-if="label" class="caption grey--text mb-2">{{ label }}</div>

          <div
            v-if="loadingCount"
            class="d-flex align-center mb-2"
            style="gap:8px;"
          >
            <v-progress-circular size="16" width="2" indeterminate color="grey" />
            <span class="caption grey--text">Checking filled posts…</span>
          </div>
          <v-alert v-else-if="!allFilled" dense text type="warning" class="mb-3">
            Not all posts have been filled yet.
          </v-alert>

          <div style="font-size:14px;color:#44403c;line-height:1.6;">
            {{ message }}
          </div>
          <div class="caption red--text text--darken-1 mt-2 font-weight-bold">
            This action cannot be undone.
          </div>

          <v-alert v-if="error" dense text type="error" class="mt-3">
            {{ error }}
          </v-alert>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn text :disabled="closing" @click="dialog = false">
            Cancel
          </v-btn>
          <v-btn
            color="error"
            depressed
            :loading="closing"
            @click="confirm"
          >
            Yes, Close Hiring
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </span>
</template>

<script>
const APP_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/application-profile";

export default {
  name: "CloseHiringButton",
  props: {
    advertId: { type: String, required: true },
    // Total advertised posts for this vacancy — used to warn if not all
    // have been filled yet. Filled-count (offered applications) is
    // resolved internally so this component is a drop-in regardless of
    // whether the parent already tracks that count.
    vacancies: { type: Number, default: 0 },
    label: { type: String, default: "" },
    buttonText: { type: String, default: "Close Hiring" },
    // Set by the parent when hiring is already closed for this
    // advertisement — disables the default button/activator slot and
    // blocks open() as defense in depth.
    disabled: { type: Boolean, default: false },
  },
  data() {
    return {
      dialog: false,
      loadingCount: false,
      offeredCount: 0,
      closing: false,
      error: null,
    };
  },
  computed: {
    allFilled() {
      return this.offeredCount >= this.vacancies;
    },
    message() {
      const base =
        "Closing hiring will notify all successful and unsuccessful candidates.";
      if (this.loadingCount) return base;
      if (this.allFilled) {
        return `${base} Are you sure you want to close hiring for this advertisement?`;
      }
      return (
        `Warning: only ${this.offeredCount} of ${this.vacancies} ` +
        `post${this.vacancies !== 1 ? "s" : ""} have been filled (offered). ` +
        `${base} Are you sure you want to close hiring anyway?`
      );
    },
  },
  methods: {
    async open() {
      if (this.disabled) return;
      this.error = null;
      this.dialog = true;
      this.loadingCount = true;
      try {
        const params = new URLSearchParams({
          _profile: APP_PROFILE,
          advertisedvacancy: "Basic/" + this.advertId,
          posappstatus: "offered",
          _count: 0,
          _total: "accurate",
        });
        const res = await fetch("/fhir/Basic?" + params.toString());
        if (res.ok) {
          const bundle = await res.json();
          this.offeredCount = bundle.total || 0;
        }
      } catch (e) {
        console.error("CloseHiringButton: failed to load offered count", e);
      } finally {
        this.loadingCount = false;
      }
    },

    async confirm() {
      this.closing = true;
      this.error = null;
      try {
        const res = await fetch(
          `/site/position/close-hiring/${this.advertId}`,
          { method: "POST" },
        );
        if (!res.ok) {
          let message = `Failed to close hiring (HTTP ${res.status}).`;
          try {
            const err = await res.json();
            message = err.message || err.error || message;
          } catch (_) {
            /* response wasn't JSON — keep default message */
          }
          throw new Error(message);
        }
        this.dialog = false;
        this.$store.commit("setMessage", {
          type: "success",
          text: "Hiring closed. Candidates are being notified.",
        });
        this.$emit("closed");
      } catch (err) {
        console.error("closeHiring error", err);
        this.error =
          err.message || "Failed to close hiring. Please try again.";
      } finally {
        this.closing = false;
      }
    },
  },
};
</script>
